// Animated skeletons ("bones", Content/Characters/Bones/<id>/). The atelier cannot draw them, so a world gets
// them by copying from another managed world's library (generated by code, nothing from Ankama).
import fs from "node:fs";
import path from "node:path";
import { AtelierError } from "./errors";

const BONES = path.join("Content", "Characters", "Bones");
const idsIn = (dir: string): number[] => {
  const d = path.join(dir, BONES);
  if (!fs.existsSync(d)) return [];
  return fs.readdirSync(d, { withFileTypes: true }).filter((e) => e.isDirectory() && /^\d{1,12}$/.test(e.name)).map((e) => Number(e.name)).sort((a, b) => a - b);
};

export interface BoneLibrary {
  own: number[];
  /** bones other worlds hold and this one lacks */
  library: { world: string; id: number }[];
}

export function listBones(dir: string, others: Record<string, string>): BoneLibrary {
  const own = idsIn(dir);
  const have = new Set(own);
  const library: BoneLibrary["library"] = [];
  for (const [world, d] of Object.entries(others)) for (const id of idsIn(d)) if (!have.has(id)) { library.push({ world, id }); have.add(id); }
  return { own, library };
}

export function copyBone(dir: string, fromDir: string, id: number): void {
  if (!idsIn(fromDir).includes(id)) throw new AtelierError(404, `squelette ${id} introuvable dans ce monde`);
  const dest = path.join(dir, BONES, String(id));
  if (fs.existsSync(dest)) throw new AtelierError(409, `squelette ${id} déjà présent`);
  fs.cpSync(path.join(fromDir, BONES, String(id)), dest, { recursive: true });
}
